arguments.command:
python3 -c '
import json, re

def strict_gsm8k_extract(solution_str):
    # Standard verl gsm8k extraction
    solutions = re.findall("#### (\-?[0-9\.\,]+)", solution_str)
    if not solutions:
        return None
    return solutions[-1].replace(",", "").rstrip(".")

def last_number_extract(solution_str):
    nums = re.findall(r"-?\d[\d,]*(?:\.\d+)?", solution_str)
    if not nums:
        return None
    return nums[-1].replace(",", "").rstrip(".")

def boxed_extract(solution_str):
    m = re.findall(r"\boxed\{([^}]+)\}", solution_str)
    if not m:
        return None
    return m[-1].replace(",", "").strip()

for step in [0, 50, 100]:
    with open(f"/workspace/results/run100/val_generations/{step}.jsonl") as f:
        rows = [json.loads(line) for line in f]
    print(f"=== VAL STEP {step} (n={len(rows)}) ===")
    print("Keys:", rows[0].keys())
    print("Sample 0:", {k: (v[:200] if isinstance(v, str) else v) for k, v in rows[0].items()})
'

